/**
 * Icons converted from the Figma exports for node 2:3.
 *
 * The only edit made to the exported geometry is swapping hardcoded fills and
 * strokes to `currentColor`, so each glyph inherits its color from the parent's
 * text token rather than pinning a hex.
 *
 * Four of these came from Iconify sets the designer picked (carbon:add-filled,
 * ic:round-auto-mode, fa6-solid:chart-line, radix-icons:check); the rest are
 * custom vectors with no Iconify equivalent.
 */

/*
 * SIZING
 *
 * Every icon is sized in rem, not px. SVG width/height attributes are px and
 * would NOT scale with the global --ui-scale knob, so a chevron would stay
 * large while the type around it shrank.
 *
 * Props stay numeric and keep reading as their Figma export dimensions — they
 * are just interpreted against a 16px base and emitted as rem. rem rather than
 * em is deliberate: it ties icons to the global scale rather than to whatever
 * font-size they happen to sit in, so the same glyph is the same size in an
 * 11px column head and a 13px table row.
 */
const BASE = 16;

/** 30 -> "1.875rem" */
function rem(px: number): string {
  return `${px / BASE}rem`;
}

type IconProps = {
  className?: string;
  width?: number;
  height?: number;
};

export type ChevronDirection = "up" | "down" | "left" | "right";

const CHEVRON_ROTATION: Record<ChevronDirection, string> = {
  down: "",
  up: "rotate-180",
  // Figma rotates the same down-chevron for the month stepper arrows.
  left: "rotate-90",
  right: "-rotate-90",
};

/**
 * ONE chevron for all six call sites in the design.
 *
 * Figma contains instances at 24x12, 15x7.5, 14x7, 12x6 and 12x24 — every one
 * is this same 2:1 glyph, scaled, with the month arrows rotated 90 degrees.
 * Height is derived as width/2 so the aspect ratio can't drift.
 */
export function Chevron({
  width = 14,
  direction = "down",
  className = "",
}: {
  width?: number;
  direction?: ChevronDirection;
  className?: string;
}) {
  return (
    <svg
      width={rem(width)}
      height={rem(width / 2)}
      viewBox="0 0 28 16"
      fill="none"
      aria-hidden="true"
      focusable="false"
      className={`shrink-0 ${CHEVRON_ROTATION[direction]} ${className}`}
      style={{ overflow: "visible" }}
    >
      <path
        d="M26 2L14 14L2 2"
        stroke="currentColor"
        strokeWidth={4}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

